    {"role": "user", "content": "¿Recuerdas mi nombre y profesión?"}
  ]
}

{
  "model": "gpt-5-5",
  "messages": [
    {
      "role": "user",
      "content": [
        {
          "type": "text",
          "text": "Resume el documento adjunto en 3 puntos clave y extrae las ideas principales."
        },
        {
          "type": "file",
          "file": {
            "file_id": "{{file_id}}"
          }
        }
      ]
    }
  ]
}

{
  "model": "gpt-4o",
  "messages": [
    {"role": "user", "content": "¿Cuál es la diferencia entre TCP y UDP?"}
  ]
